void screen_idle_lock_time_update(lv_obj_t * ui_ScreenidleLock)
{
    uint8_t         nongli_month[2] = {
        0
        };
    ui_screenidle_lock_obj_t * p_screen_param;
    uint8_t         buf[20],i;
    aos_systime     cur_time = {
        0
        };
    p_screen_param      = (ui_screenidle_lock_obj_t *) lv_obj_get_user_data(ui_ScreenidleLock);

    aos_get_systime(&cur_time);
    i                   = 0;
    buf[i++]            = cur_time.hour / 10;
    buf[i++]            = cur_time.hour % 10;
    buf[i++]            = 10;
    buf[i++]            = cur_time.minute / 10;
    buf[i++]            = cur_time.minute % 10;
    img_label_set_text(p_screen_param->img_label[OBJ_NUM_HOUR_MIN],buf,i);

    i                   = 0;
    buf[i++]            = cur_time.year / 1000;
    buf[i++]            = cur_time.year % 1000 / 100;
    buf[i++]            = cur_time.year % 1000 % 100 / 10;
    buf[i++]            = cur_time.year % 1000 % 100 % 10;

    buf[i++]            = 10;

    buf[i++]            = cur_time.month / 10;
    buf[i++]            = cur_time.month % 10;

    buf[i++]            = 10;

    buf[i++]            = cur_time.day / 10;
    buf[i++]            = cur_time.day % 10;
    img_label_set_text(p_screen_param->img_label[OBJ_NUM_YEAR_MON_DAY],buf,i);
    nongli_num(cur_time.year,cur_time.month,cur_time.day,nongli_month);

    lv_img_set_src(p_screen_param->obj_img[OBJ_IMG_WEEK],ui_imgset_week[cur_time.wday]);


    i                   = 0;
    buf[i++]            = nongli_month[1] -1;
    buf[i++]            = 12;
    img_label_set_text(p_screen_param->img_label[OBJ_NUM_MONTH],buf,i);

    i                   = 0;

    //buf[i++] = 10+(nongli_month[0]-1)/10;
    //buf[i++] = 10+(nongli_month[0]-1)/10;
    if (nongli_month[0] <= 10) {
        buf[i++]            = 10;
        buf[i++]            = (nongli_month[0] -1) % 10;
        }
    else if (nongli_month[0] < 20) {
        buf[i++]            = 11;
        buf[i++]            = (nongli_month[0] -1) % 10;
        }
    else if (nongli_month[0] == 20) {
        buf[i++]            = 2 - 1;
        buf[i++]            = 10 - 1;
        }
    else if (nongli_month[0] == 30) {
        buf[i++]            = 3 - 1;
        buf[i++]            = 10 - 1;

        }
    else {
        buf[i++]            = 12;
        buf[i++]            = (nongli_month[0] -1) % 10;
        }

    img_label_set_text(p_screen_param->img_label[OBJ_NUM_DAY],buf,i);
}




