void remind_timer_callback_screen_idle_lock(idle_lock_screen_remind_param_t * p_param)
{
    lv_obj_t *      ui_Screen;

    ui_Screen           = p_param->user_data;

    if (p_param->key == 0x80) //表示已经解锁，跳转到待机界面
    {
        alv_am_win_exit_action(NULL,"idle_lock",NULL);
        }
    else if (p_param->key == LV_KEY_END) {
        alv_am_win_jump_action(NULL,"watch",NULL);

        alv_am_win_exit_action(NULL,"idle_lock",NULL);
        }
    else 
        lv_disp_load_scr(ui_Screen);
}


void screen_idle_lock_key_event(uint32_t key,lv_obj_t * ui_Screen)
{
    ui_screenidle_lock_obj_t * p_screen_param;

    p_screen_param      = (ui_screenidle_lock_obj_t *) lv_obj_get_user_data(ui_Screen);

    switch (key)
    {
        case LV_KEY_ESC:
            {
                idle_lock_screen_remind_param_t idle_lock_screen_remind_param;
                lv_obj_t *      ui_screen;

                ui_screen_remind_param_init((screen_remind_param_t *) &idle_lock_screen_remind_param);

                idle_lock_screen_remind_param.str = "请按右软键解锁";
                idle_lock_screen_remind_param.tiemr_delay = 2000;
                idle_lock_screen_remind_param.fun =
                     (idle_lock_remind_timer_callback_fun_t) remind_timer_callback_screen_idle_lock;
                idle_lock_screen_remind_param.user_data = ui_Screen;
                p_screen_param->key = LV_KEY_ESC;
                idle_lock_screen_remind_param.key = LV_KEY_ESC;
                ui_screen           = ui_idle_lock_screen_remind_init(&idle_lock_screen_remind_param);

                lv_disp_load_scr(ui_screen);


                }
            break;

        case LV_KEY_END:
            {
                idle_lock_screen_remind_param_t idle_lock_screen_remind_param;
                lv_obj_t *      ui_screen;

                ui_screen_remind_param_init((screen_remind_param_t *) &idle_lock_screen_remind_param);

                idle_lock_screen_remind_param.str = "键盘已解锁";
                idle_lock_screen_remind_param.tiemr_delay = 1500;
                idle_lock_screen_remind_param.fun =
                     (idle_lock_remind_timer_callback_fun_t) remind_timer_callback_screen_idle_lock;
                idle_lock_screen_remind_param.user_data = ui_Screen;
                p_screen_param->key = LV_KEY_END;
                idle_lock_screen_remind_param.key = LV_KEY_END;
                ui_screen           = ui_idle_lock_screen_remind_init(&idle_lock_screen_remind_param);

                lv_disp_load_scr(ui_screen);

                app_fp_play_tts_lock_lcd(idle_lock_screen_remind_param.str);

                }
            break;
        case LV_KEY_ENTER:
            break;
        default:
            {
                idle_lock_screen_remind_param_t idle_lock_screen_remind_param;
                lv_obj_t *      ui_screen;

                ui_screen_remind_param_init((screen_remind_param_t *) &idle_lock_screen_remind_param);

                idle_lock_screen_remind_param.str = "请按左软键+右软键解锁或电源键解锁";
                idle_lock_screen_remind_param.tiemr_delay = 2000;
                idle_lock_screen_remind_param.fun =
                     (idle_lock_remind_timer_callback_fun_t) remind_timer_callback_screen_idle_lock;
                idle_lock_screen_remind_param.user_data = ui_Screen;
                p_screen_param->key = 0;
                idle_lock_screen_remind_param.key = 0;
                ui_screen           = ui_idle_lock_screen_remind_init(&idle_lock_screen_remind_param);

                lv_disp_load_scr(ui_screen);


                }
            break;
        }
}


